// @FIGURE_CODE_BEGIN
(function () {
  var VW = 960, VH = 278;
  var C = {
    gray: '#dedede',
    rect: '#d6d6d6',
    hi: '#ffd98a',
    hiText: '#8a4b00',
    line: '#000',
    note: '#666'
  };
  var SERIF = '"Times New Roman", Times, serif';

  var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
  draw.viewbox(0, 0, VW, VH);

  var state = { mode: 'both', level: 0, hi: false };
  var LEVELS = ['root only', 'first split', 'second split', 'grandchildren'];

  /* ---------- small drawing helpers ---------- */
  function mtext(parts, x, y, size, anchor, fill) {
    var t = draw.text(function (add) {
      parts.forEach(function (p) {
        var s = add.tspan(p[0]);
        if (p[1]) s.font({ style: 'italic' });
      });
    });
    t.font({ family: SERIF, size: size, anchor: anchor || 'middle' });
    t.attr({ x: x, y: y, 'dominant-baseline': 'central' });
    if (fill) t.fill(fill);
    return t;
  }
  function plain(str, x, y, size, fill, anchor) {
    var t = draw.text(str);
    t.font({ family: 'sans-serif', size: size, anchor: anchor || 'middle' });
    t.attr({ x: x, y: y, 'dominant-baseline': 'central' });
    t.fill(fill || C.note);
    return t;
  }
  function edge(x1, y1, x2, y2) {
    return draw.line(x1, y1, x2, y2).stroke({ color: C.line, width: 1.6, linecap: 'round' });
  }
  function grayRect(cx, cy, w, h) {
    return draw.rect(w, h).center(cx, cy).fill(C.rect);
  }
  function dottedArrow(x1, x2, y) {
    var g = draw.group();
    g.line(x1, y, x2 - 12, y).stroke({ color: C.line, width: 5.5, dasharray: '2.5,7', linecap: 'butt' });
    g.polygon([[x2, y], [x2 - 12, y - 6.5], [x2 - 12, y + 6.5]]).fill(C.line);
    return g;
  }
  function inter(el, tip, title, body, cursor) {
    el.css('cursor', cursor || 'help');
    el.on('mousemove', function (e) { showTooltip(tip, e); });
    el.on('mouseleave', function () { hideTooltip(); });
    if (title) el.on('click', function () { showPopup(title, body); });
    return el;
  }

  /* ---------- label token sets ---------- */
  var T_n = [['n', true]];
  var T_n1 = [['n', true], ['\u22121', false]];
  var T_half = [['(', false], ['n', true], ['\u22121)/2', false]];
  var T_halfm1 = [['(', false], ['n', true], ['\u22121)/2 \u2212 1', false]];
  var T_theta = [['\u0398(', false], ['n', true], [')', false]];
  var T_quarter = [['\u2248', false], ['n', true], ['/4', false]];

  /* ---------- panel (a) ---------- */
  function drawPanelA() {
    var lvl = state.level;
    var hiFill = state.hi ? C.hi : C.gray;
    var nodeFill = state.hi ? C.hiText : '#000';

    // shaded grouping ellipse (drawn first, lines go over it)
    if (lvl >= 1) {
      var e;
      if (lvl >= 2) {
        e = draw.ellipse(188, 80).center(171, 76).rotate(36, 171, 76);
      } else {
        e = draw.ellipse(56, 36).center(116, 36);
      }
      e.fill(hiFill);
      inter(e, 'Partitioning work bundled into a single \u0398(n) charge',
        'One \u0398(n) charge for the pair of levels',
        'The shaded region bundles the partitioning of the n-element array (the bad split) together with the partitioning of the n\u22121-element array (the good split). Their combined cost is \u0398(n) + \u0398(n\u22121) = \u0398(n) \u2014 one level\u2019s worth of work, only with a larger constant.',
        'pointer');
      e.on('click', function () { state.hi = !state.hi; syncHiBox(); render(); });
    }

    // edges
    if (lvl >= 1) { edge(108, 45, 34, 99); edge(126, 45, 204, 100); }
    if (lvl >= 2) { edge(210, 120, 172, 146); edge(222, 120, 256, 146); }

    // subproblem boxes
    if (lvl >= 2) {
      inter(grayRect(151, 171, 118, 50),
        'Subproblem still to be solved: (n\u22121)/2 \u2212 1 elements',
        'Remaining subproblem',
        'After the bad split and the good split that follows, this part of the array still has about (n\u22121)/2 elements and must be sorted recursively.');
      inter(grayRect(281, 171, 85, 50),
        'Subproblem still to be solved: (n\u22121)/2 elements',
        'Remaining subproblem',
        'The other half left by the good partition, also of size about (n\u22121)/2 \u2014 exactly the sizes a single balanced partition would have produced.');
    }
    if (lvl >= 3) {
      edge(151, 196, 120, 204); edge(151, 196, 182, 204);
      edge(281, 196, 253, 204); edge(281, 196, 311, 204);
      [120, 182, 253, 311].forEach(function (cx) {
        inter(grayRect(cx, 215, 52, 22),
          'Next level of subproblems, size \u2248 n/4',
          'One level deeper',
          'Each surviving subproblem is partitioned again. Both fragments march downward at the same rate, so the alternating pattern does not add depth to the recursion tree.');
      });
    }

    // dotted cost arrow
    if (lvl >= 1) {
      var ay = (lvl >= 2) ? 74 : 40;
      var ax = (lvl >= 2) ? 246 : 148;
      var arrow = dottedArrow(ax, 348, ay);
      var th = mtext(T_theta, 360, ay, 21, 'start');
      [arrow, th].forEach(function (el) {
        inter(el, 'Total partitioning cost charged here: \u0398(n)',
          'Key insight',
          'A bad split absorbed into the next good split costs the same \u0398(n) as one good split alone \u2014 so alternating bad and good partitions only changes the constant, not the O(n lg n) running time.',
          'pointer');
      });
    }

    // node labels (on top)
    inter(mtext(T_n, 116, 35, 20, 'middle', nodeFill),
      'Root subproblem of size n', 'Subproblem of size n',
      'The whole array before any partitioning. Partitioning it costs \u0398(n) no matter how balanced the split turns out to be.');
    if (lvl >= 1) {
      inter(mtext([['0', false]], 20, 109, 20),
        'Worst-case split: an empty side (0 elements)',
        'A worst-case partition',
        'The pivot ends up at an end of the array, so one side is empty and the other has n\u22121 elements. Work was done, but almost no progress was made.');
      inter(mtext(T_n1, 216, 110, 20, 'middle', nodeFill),
        'Subproblem of size n\u22121 after the bad split',
        'Almost no progress',
        'The bad partition leaves n\u22121 elements \u2014 essentially the original problem. The next partition, if it is balanced, splits this into two nearly equal halves.');
    }

    // caption + running cost
    var capY = (lvl >= 3) ? 246 : 219;
    mtext([['(a)', false]], 155, capY, 18);
    plain(costA(lvl), 200, capY + 18, 10.5);
  }

  function costA(l) {
    if (l === 0) return 'nothing partitioned yet \u2014 cost 0';
    if (l === 1) return 'bad split alone: cost \u0398(n)';
    if (l === 2) return 'bad + good split together: \u0398(n)';
    return 'two \u0398(n) levels charged so far';
  }

  /* ---------- panel (b) ---------- */
  function drawPanelB() {
    var lvl = state.level;
    var hiFill = state.hi ? C.hi : C.gray;
    var nodeFill = state.hi ? C.hiText : '#000';

    if (lvl >= 1) {
      var e = draw.ellipse(62, 38).center(700, 71).fill(hiFill);
      inter(e, 'One balanced partition \u2014 \u0398(n) work',
        'A single good partition',
        'Panel (b) spends one \u0398(n) partition and immediately produces two subproblems of size (n\u22121)/2 \u2014 the same sizes, to within one element, that panel (a) needed two partitions to reach.',
        'pointer');
      e.on('click', function () { state.hi = !state.hi; syncHiBox(); render(); });

      edge(690, 86, 622, 121);
      edge(710, 86, 782, 121);

      inter(grayRect(608, 145, 84, 48),
        'Subproblem still to be solved: (n\u22121)/2 elements',
        'Remaining subproblem',
        'A balanced partition leaves two subproblems of about half the size, which is what drives the lg n depth of the recursion tree.');
      inter(grayRect(797, 145, 84, 48),
        'Subproblem still to be solved: (n\u22121)/2 elements',
        'Remaining subproblem',
        'The mirror-image half. Compare with panel (a): the sizes differ by at most one element.');

      if (lvl >= 3) {
        edge(608, 169, 578, 179); edge(608, 169, 640, 179);
        edge(797, 169, 767, 179); edge(797, 169, 829, 179);
        [578, 640, 767, 829].forEach(function (cx) {
          inter(grayRect(cx, 190, 56, 22),
            'Next level of subproblems, size \u2248 n/4',
            'One level deeper',
            'Both panels reach subproblems of size about n/4 after the same amount of charged work \u2014 the alternating pattern only costs a constant factor.');
        });
      }

      var arrow = dottedArrow(735, 845, 73);
      var th = mtext(T_theta, 857, 73, 21, 'start');
      [arrow, th].forEach(function (el) {
        inter(el, 'Partitioning cost of this level: \u0398(n)',
          'Key insight',
          'A bad split absorbed into the next good split costs the same \u0398(n) as one good split alone \u2014 so alternating bad and good partitions only changes the constant, not the O(n lg n) running time.',
          'pointer');
      });
    }

    inter(mtext(T_n, 700, 73, 20, 'middle', nodeFill),
      'Root subproblem of size n', 'Subproblem of size n',
      'The same starting array as in panel (a), but here the very first partition is balanced.');

    var capY = (state.level >= 3) ? 246 : 219;
    mtext([['(b)', false]], 700, capY, 18);
    plain(costB(state.level), 700, capY + 18, 10.5);
  }

  function costB(l) {
    if (l === 0) return 'nothing partitioned yet \u2014 cost 0';
    if (l < 3) return 'one good split: cost \u0398(n)';
    return 'two \u0398(n) levels charged so far';
  }

  /* ---------- render ---------- */
  function render() {
    draw.clear();
    if (state.mode === 'a') draw.viewbox(-6, 0, 452, VH);
    else if (state.mode === 'b') draw.viewbox(524, 0, 446, VH);
    else draw.viewbox(0, 0, VW, VH);

    if (state.mode !== 'b') drawPanelA();
    if (state.mode !== 'a') drawPanelB();
  }

  /* ---------- controls ---------- */
  function syncLevelLabel() {
    var o = document.getElementById('expandLevelVal');
    if (o) o.value = LEVELS[state.level];
  }
  function syncHiBox() {
    var cb = document.getElementById('highlightGroupInput');
    if (cb) cb.checked = state.hi;
  }

  window.toggle_splitMode = function (v) {
    state.mode = v;
    render();
  };
  window.trigger_expandLevel = function () {
    state.level = (state.level >= 3) ? 0 : state.level + 1;
    syncLevelLabel();
    render();
  };
  window.trigger_reset = function () {
    state.level = 0; state.hi = false;
    syncLevelLabel(); syncHiBox(); render();
  };
  window.toggle_highlightGroup = function (on) {
    state.hi = on;
    render();
  };

  /* ---------- demo steps ---------- */
  var STEPS = [
    { title: 'Two roots of size n', mode: 'both', level: 0,
      text: 'Both fragments start from the same subproblem of size n. Nothing has been partitioned yet, so no children exist and no cost has been charged.' },
    { title: 'A worst-case split in (a)', mode: 'a', level: 1,
      text: 'In panel (a) the first partition is maximally unbalanced: it peels off an empty side (0) and leaves n\u22121. That partition still costs \u0398(n), but makes almost no progress.' },
    { title: 'A good split follows', mode: 'a', level: 2,
      text: 'The n\u22121 subproblem is then partitioned evenly into (n\u22121)/2 \u2212 1 and (n\u22121)/2. The shaded ellipse groups the bad and good partitions together \u2014 their combined cost is still only \u0398(n).' },
    { title: 'One balanced split alone', mode: 'b', level: 1,
      text: 'Panel (b) spends a single \u0398(n) partition and produces two subproblems of size (n\u22121)/2 \u2014 the same sizes, to within one element, as panel (a) ended with.' },
    { title: 'Same cost, same remaining work', mode: 'both', level: 2,
      text: 'Side by side: both fragments charged \u0398(n) and both left roughly (n\u22121)/2-sized subproblems. The bad split cost only a constant factor, not an extra level of depth.' },
    { title: 'Continuing downward', mode: 'both', level: 3,
      text: 'Expanding one more level shows both trees marching toward the same depth, which is why alternating bad and good partitions still runs in O(n lg n).' }
  ];
  var step = 0;

  function applyStep(i) {
    step = (i + STEPS.length) % STEPS.length;
    var s = STEPS[step];
    state.mode = s.mode;
    state.level = s.level;
    var sel = document.getElementById('splitModeInput');
    if (sel) sel.value = s.mode;
    syncLevelLabel();
    var n = document.getElementById('demoNarration');
    if (n) n.innerHTML = '<b>' + s.title + '</b><br>' + s.text;
    var lab = document.getElementById('stepLabel');
    if (lab) lab.textContent = 'step ' + (step + 1) + ' / ' + STEPS.length;
    render();
  }
  window.nextStep = function () { applyStep(step + 1); };
  window.prevStep = function () { applyStep(step - 1); };

  applyStep(0);
  window.__markRendered();
})();
