    if (state.mode !== 'a') drawPanelB();
  }

  /* ---------- controls ---------- */
  function syncLevelLabel() {
    var o = document.getElementById('expandLevelVal');
    if (o) o.value = LEVELS[state.level];
  }
  function syncHiBox() {
    var cb = document.getElementById('highlightGroupInput');
    if (cb) cb.checked = state.hi;
  }

  window.toggle_splitMode = function (v) {
    state.mode = v;
    render();
  };
  window.trigger_expandLevel = function () {
    state.level = (state.level >= 3) ? 0 : state.level + 1;
    syncLevelLabel();
    render();
  };
  window.trigger_reset = function () {
    state.level = 0; state.hi = false;
    syncLevelLabel(); syncHiBox(); render();
  };
  window.toggle_highlightGroup = function (on) {
    state.hi = on;
    render();
  };

  /* ---------- demo steps ---------- */
  var STEPS = [
    { title: 'Two roots of size n', mode: 'both', level: 0,
      text: 'Both fragments start from the same subproblem of size n. Nothing has been partitioned yet, so no children exist and no cost has been charged.' },
    { title: 'A worst-case split in (a)', mode: 'a', level: 1,
      text: 'In panel (a) the first partition is maximally unbalanced: it peels off an empty side (0) and leaves n\u22121. That partition still costs \u0398(n), but makes almost no progress.' },
    { title: 'A good split follows', mode: 'a', level: 2,
      text: 'The n\u22121 subproblem is then partitioned evenly into (n\u22121)/2 \u2212 1 and (n\u22121)/2. The shaded ellipse groups the bad and good partitions together \u2014 their combined cost is still only \u0398(n).' },
    { title: 'One balanced split alone', mode: 'b', level: 1,
      text: 'Panel (b) spends a single \u0398(n) partition and produces two subproblems of size (n\u22121)/2 \u2014 the same sizes, to within one element, as panel (a) ended with.' },
    { title: 'Same cost, same remaining work', mode: 'both', level: 2,
      text: 'Side by side: both fragments charged \u0398(n) and both left roughly (n\u22121)/2-sized subproblems. The bad split cost only a constant factor, not an extra level of depth.' },
    { title: 'Continuing downward', mode: 'both', level: 3,
      text: 'Expanding one more level shows both trees marching toward the same depth, which is why alternating bad and good partitions still runs in O(n lg n).' }
  ];
  var step = 0;

  function applyStep(i) {
    step = (i + STEPS.length) % STEPS.length;
    var s = STEPS[step];
    state.mode = s.mode;
    state.level = s.level;
    var sel = document.getElementById('splitModeInput');
    if (sel) sel.value = s.mode;
    syncLevelLabel();
    var n = document.getElementById('demoNarration');
    if (n) n.innerHTML = '<b>' + s.title + '</b><br>' + s.text;
    var lab = document.getElementById('stepLabel');
    if (lab) lab.textContent = 'step ' + (step + 1) + ' / ' + STEPS.length;
    render();
  }
  window.nextStep = function () { applyStep(step + 1); };
  window.prevStep = function () { applyStep(step - 1); };

  applyStep(0);
  window.__markRendered();
})();
// @FIGURE_CODE_END

