// @FIGURE_CODE_BEGIN
(function () {
  var VW = 1000, VH = 300;
  var SERIF = '"Times New Roman", Times, serif';
  var C = {
    ell: '#dcdcdc',
    box: '#d5d5d5',
    hi: '#ffd98a',
    hiTxt: '#7a4400',
    line: '#000'
  };

  var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
  draw.viewbox(0, 0, VW, VH);

  var STAGES = ['complete', 'roots', 'first', 'second'];
  var STAGE_LABEL = {
    complete: 'complete figure',
    roots: 'roots only',
    first: 'after first split',
    second: 'after second split'
  };

  var state = { stage: 'complete', focus: 'both', hiEll: false, hiBox: false };

  /* ---------------- token sets ---------------- */
  var T_n = [['n', true]];
  var T_zero = [['0', false]];
  var T_n1 = [['n', true], ['\u20131', false]];
  var T_half = [['(', false], ['n', true], ['\u20131)/2', false]];
  var T_halfm1 = [['(', false], ['n', true], ['\u20131)/2 \u2212 1', false]];
  var T_theta = [['\u0398(', false], ['n', true], [')', false]];

  /* ---------------- helpers ---------------- */
  function mtext(g, tokens, x, y, size, anchor, fill) {
    var t = g.text(function (add) {
      tokens.forEach(function (tk) {
        var s = add.tspan(tk[0]);
        if (tk[1]) s.font({ style: 'italic' });
      });
    });
    t.font({ family: SERIF, size: size, anchor: anchor || 'middle' });
    t.attr({ x: x, y: y, 'dominant-baseline': 'central' });
    try {
      t.children().forEach(function (s) {
        if (s.attr('x') != null) s.attr('x', null);
        s.attr('dy', 0);
      });
    } catch (e) { /* ignore */ }
    t.fill(fill || '#000');
    return t;
  }

  function edge(g, x1, y1, x2, y2) {
    return g.line(x1, y1, x2, y2).stroke({ color: C.line, width: 1.8, linecap: 'round' });
  }

  function inter(el, tip, title, body, cursor) {
    el.css('cursor', cursor || 'help');
    el.on('mousemove', function (e) { showTooltip(tip, e); });
    el.on('mouseleave', function () { hideTooltip(); });
    if (title) el.on('click', function (ev) { ev.stopPropagation(); showPopup(title, body); });
    return el;
  }

  function hitArea(g, x, y, w, h) {
    return g.rect(w, h).move(x, y).fill('#ffffff')
      .attr({ 'fill-opacity': 0.001, 'pointer-events': 'all' });
  }

  function dottedArrow(g, x1, x2, y) {
    g.line(x1, y, x2 - 15, y)
      .stroke({ color: C.line, width: 7.5, dasharray: '3,10', linecap: 'butt' });
    g.polygon([[x2, y], [x2 - 15, y - 8], [x2 - 15, y + 8]]).fill(C.line);
    g.line(x2 - 19, y - 9, x2 - 19, y + 9).stroke({ color: C.line, width: 3 });
  }

  function makeBox(g, cx, cy, tokens, minW, h) {
    var t = mtext(g, tokens, cx, cy, 28, 'middle', state.hiBox ? C.hiTxt : '#000');
    var bw = minW;
    try { var bb = t.bbox(); if (bb && bb.width) bw = Math.max(minW, bb.width + 42); } catch (e) { }
    var r = g.rect(bw, h).center(cx, cy).fill(state.hiBox ? C.hi : C.box);
    t.front();
    return { rect: r, text: t, w: bw };
  }

  var BOX_TIP = 'Subproblem still to be solved \u2014 about (n\u22121)/2 elements';
  var BOX_TITLE = 'Leftover subproblem';
  var BOX_BODY = 'Panel (a) needed two partitions (one bad, one good) to reach these pieces; panel (b) needed only one. Yet the sizes agree to within a single element, so the remaining work is the same. Click again to unhighlight.';

  function boxInteract(b) {
    [b.rect, b.text].forEach(function (el) {
      inter(el, BOX_TIP, BOX_TITLE, BOX_BODY, 'pointer');
      el.on('click', function () {
        state.hiBox = !state.hiBox;
        var cb = document.getElementById('matchBoxesInput');
        if (cb) cb.checked = state.hiBox;
        render();
      });
    });
  }

  var ARROW_TITLE = 'The key insight';
  var ARROW_BODY = 'A bad split absorbed into the next good split costs the same \u0398(n) as one good split alone, and leaves subproblems of the same size. Alternating bad and good partitions therefore changes only the constant factor \u2014 the running time is still O(n lg n).';

  function ellipseInteract(el, tip, title, body) {
    inter(el, tip, title, body, 'pointer');
    el.on('click', function () {
      state.hiEll = !state.hiEll;
      var cb = document.getElementById('highlightGroupInput');
      if (cb) cb.checked = state.hiEll;
      render();
    });
  }

  /* ---------------- panel (a) ---------------- */
  function drawPanelA(g) {
    var st = state.stage;
    var show1 = (st !== 'roots');
    var show2 = (st === 'second' || st === 'complete');
    var nodeFill = state.hiEll && show1 ? C.hiTxt : '#000';

    // shaded grouping ellipse (behind everything)
    if (show1) {
      var e = g.ellipse(236, 100).center(208, 104).rotate(41, 208, 104)
        .fill(state.hiEll ? C.hi : C.ell);
      ellipseInteract(e,
        'Bad split + the good split that follows \u2014 charged \u0398(n) together',
        'One \u0398(n) charge for the pair',
        'The shaded region bundles the partitioning of the n-element array (the bad split) with the partitioning of the n\u22121-element array (the good split). Their combined cost is \u0398(n) + \u0398(n\u22121) = \u0398(n) \u2014 a single level\u2019s worth of work with a slightly larger constant.');
    }

    // edges
    if (show1) {
      edge(g, 136, 70, 62, 140);
      edge(g, 164, 70, 244, 134);
    }
    if (show2) {
      edge(g, 252, 170, 180, 201);
      edge(g, 278, 170, 330, 201);
    }

    // boxes
    if (show2) {
      boxInteract(makeBox(g, 150, 232, T_halfm1, 150, 62));
      boxInteract(makeBox(g, 316, 232, T_half, 112, 62));
    }

    // dotted arrow + Theta(n)
    if (show1) {
      dottedArrow(g, 312, 438, 88);
      var th = mtext(g, T_theta, 452, 88, 34, 'start');
      var hit = hitArea(g, 306, 72, 200, 34);
      inter(th, 'Total partitioning cost charged here: \u0398(n)', ARROW_TITLE, ARROW_BODY, 'pointer');
      inter(hit, 'Total partitioning cost charged here: \u0398(n)', ARROW_TITLE, ARROW_BODY, 'pointer');
    }

    // node labels on top
    inter(mtext(g, T_n, 150, 55, 30, 'middle', nodeFill),
      'Root subproblem of size n',
      'Subproblem of size n',
      'The whole array before any partitioning. Partitioning it costs \u0398(n) no matter how balanced the resulting split turns out to be.');
    if (show1) {
      inter(mtext(g, T_zero, 48, 152, 30),
        'Worst-case split: an empty side (0 elements)',
        'A worst-case partition',
        'The pivot lands at an end of the array, so one side is empty and the other holds n\u22121 elements. Full \u0398(n) work was done, yet almost no progress was made.');
      inter(mtext(g, T_n1, 265, 152, 30, 'middle', nodeFill),
        'Subproblem of size n\u22121 left by the bad split',
        'Almost no progress',
        'The bad partition leaves n\u22121 elements \u2014 essentially the original problem. The next partition, assumed balanced, splits this into two nearly equal halves.');
    }

    mtext(g, [['(a)', true]], 190, 288, 30);
  }

  /* ---------------- panel (b) ---------------- */
  function drawPanelB(g) {
    var st = state.stage;
    var show1 = (st !== 'roots');
    var nodeFill = state.hiEll && show1 ? C.hiTxt : '#000';

    if (show1) {
      var e = g.ellipse(80, 50).center(740, 86).fill(state.hiEll ? C.hi : C.ell);
      ellipseInteract(e,
        'A single balanced partition \u2014 \u0398(n) work',
        'One good partition',
        'Panel (b) spends one \u0398(n) partition and immediately produces two subproblems of size (n\u22121)/2 \u2014 the same sizes, to within one element, that panel (a) reached only after two partitions.');

      edge(g, 724, 104, 668, 184);
      edge(g, 756, 104, 828, 184);

      boxInteract(makeBox(g, 640, 215, T_half, 112, 62));
      boxInteract(makeBox(g, 852, 215, T_half, 112, 62));

      dottedArrow(g, 786, 892, 88);
      var th = mtext(g, T_theta, 906, 88, 34, 'start');
      var hit = hitArea(g, 780, 72, 190, 34);
      inter(th, 'Partitioning cost of this level: \u0398(n)', ARROW_TITLE, ARROW_BODY, 'pointer');
      inter(hit, 'Partitioning cost of this level: \u0398(n)', ARROW_TITLE, ARROW_BODY, 'pointer');
    }

    inter(mtext(g, T_n, 740, 88, 30, 'middle', nodeFill),
      'Root subproblem of size n',
      'Subproblem of size n',
      'The same starting array as in panel (a) \u2014 but here the very first partition is balanced.');

    mtext(g, [['(b)', true]], 740, 288, 30);
  }

  /* ---------------- render ---------------- */
  function render() {
    draw.clear();
    var gA = draw.group();
    var gB = draw.group();
    drawPanelA(gA);
    drawPanelB(gB);
    gA.opacity(state.focus === 'b' ? 0.16 : 1);
    gB.opacity(state.focus === 'a' ? 0.16 : 1);
  }

  /* ---------------- controls ---------------- */
  function syncStageLabel() {
    var o = document.getElementById('buildStageVal');
    if (o) o.value = STAGE_LABEL[state.stage];
  }
  function syncFocus() {
    var s = document.getElementById('compareFocusInput');
    if (s) s.value = state.focus;
  }

  window.trigger_buildStage = function () {
    var i = STAGES.indexOf(state.stage);
    state.stage = STAGES[(i + 1) % STAGES.length];
    syncStageLabel();
    render();
  };
  window.trigger_reset = function () {
    state.stage = 'complete';
    state.focus = 'both';
    state.hiEll = false;
    state.hiBox = false;
    var a = document.getElementById('highlightGroupInput'); if (a) a.checked = false;
    var b = document.getElementById('matchBoxesInput'); if (b) b.checked = false;
    syncStageLabel(); syncFocus(); render();
  };
  window.toggle_compareFocus = function (v) { state.focus = v; render(); };
  window.toggle_highlightGroup = function (on) { state.hiEll = on; render(); };
  window.toggle_matchBoxes = function (on) { state.hiBox = on; render(); };

  /* ---------------- demo steps ---------------- */
  var STEPS = [
    {
      title: 'The figure as printed', stage: 'complete', focus: 'both',
      text: 'Both fragments are shown complete: (a) a bad split into 0 and n\u22121 followed by an even split, and (b) a single even split. Each shaded region is charged \u0398(n).'
    },
    {
      title: 'Start from the same subproblem', stage: 'roots', focus: 'both',
      text: 'Optional replay: strip both panels back to their roots. Each begins with an identical subproblem of size n and no cost charged yet.'
    },
    {
      title: 'A worst-case split in (a)', stage: 'first', focus: 'a',
      text: 'Panel (a)\u2019s first partition is maximally unbalanced: it peels off an empty side (0) and leaves n\u22121. It still costs \u0398(n) but makes almost no progress.'
    },
    {
      title: 'A good split absorbs it', stage: 'second', focus: 'a',
      text: 'The n\u22121 subproblem splits evenly into (n\u22121)/2 \u2212 1 and (n\u22121)/2. The tilted ellipse groups the bad and good partitions together \u2014 their combined cost is still only \u0398(n).'
    },
    {
      title: 'One balanced split alone', stage: 'first', focus: 'b',
      text: 'Panel (b) spends a single \u0398(n) partition and produces two subproblems of size (n\u22121)/2 \u2014 the same sizes, to within one element, as panel (a) ended with.'
    },
    {
      title: 'Same cost, same remaining work', stage: 'complete', focus: 'both',
      text: 'Back to the full figure: both fragments charged \u0398(n) and both left \u2248(n\u22121)/2-sized subproblems. The bad split cost only a constant factor, not extra depth.'
    }
  ];
  var step = 0;

  function applyStep(i) {
    step = (i + STEPS.length) % STEPS.length;
