<!-- @FIGURE_UI_BEGIN -->
<p id="demoNarration" style="margin:0;font-size:11.5px;line-height:1.5;"></p>
<span style="display:flex;gap:6px;align-items:center;">
  <button onclick="prevStep()">◀</button>
  <span id="stepLabel" style="font-size:11px;flex:1;text-align:center;color:#444;"></span>
  <button onclick="nextStep()">▶</button>
</span>
<label>Construction stage: <output id="buildStageVal">complete figure</output></label>
<span style="display:flex;gap:6px;">
  <button id="buildStageInput" onclick="trigger_buildStage()">Replay construction ▸</button>
  <button onclick="trigger_reset()">Full figure</button>
</span>
<label>Focus:
  <select id="compareFocusInput" onchange="toggle_compareFocus(this.value)">
