  </select>
</label>
<label style="flex-direction:row;align-items:center;gap:6px;"><input id="highlightGroupInput" type="checkbox" onchange="toggle_highlightGroup(this.checked)"><span>Highlight the bundled &Theta;(<i>n</i>) work</span></label>
<label style="flex-direction:row;align-items:center;gap:6px;"><input id="matchBoxesInput" type="checkbox" onchange="toggle_matchBoxes(this.checked)"><span>Highlight the leftover subproblems</span></label>
